import{_ as p,a0 as l,w as o,s as r,I as t,x as i,a1 as e,A as a,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何記錄你在終端中執行的所有操作 | LCTT x X-CMD","titleTemplate":false,"description":"如何記錄你在終端中執行的所有操作 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何記錄你在終端中執行的所有操作 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何記錄你在終端中執行的所有操作 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20170309 How To Record Everything You Do In Terminal","title":"如何記錄你在終端中執行的所有操作","tag":"201807","desc":""},"relativePath":"201807/20170309 How To Record Everything You Do In Terminal.md","filePath":"[post].md"}'),g={name:"201807/20170309 How To Record Everything You Do In Terminal.md"};function h(u,s,k,c,m,b){const n=l("Link");return o(),r("div",null,[s[26]||(s[26]=t("h1",{id:"如何記錄你在終端中執行的所有操作",tabindex:"-1"},[i("如何記錄你在終端中執行的所有操作 "),t("a",{class:"header-anchor",href:"#如何記錄你在終端中執行的所有操作","aria-label":"Permalink to “如何記錄你在終端中執行的所有操作”"},"​")],-1)),s[27]||(s[27]=t("p",null,[t("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/03/Record-Everything-You-Do-In-Terminal-720x340.png",alt:""})],-1)),t("p",null,[s[1]||(s[1]=i("幾天前，我們發佈了一個解釋如何",-1)),e(n,{href:"https://www.ostechnix.com/save-commands-terminal-use-demand/"},{default:a(()=>[...s[0]||(s[0]=[i("保存終端中的命令並按需使用",-1)])]),_:1}),s[2]||(s[2]=i("的指南。對於那些不想記憶冗長的 Linux 命令的人來説，這非常有用。今天，在本指南中，我們將看到如何使用 ",-1)),s[3]||(s[3]=t("code",null,"script",-1)),s[4]||(s[4]=i(" 命令記錄你在終端中執行的所有操作。你可能已經在終端中運行了一個命令，或創建了一個目錄，或者安裝了一個程序。",-1)),s[5]||(s[5]=t("code",null,"script",-1)),s[6]||(s[6]=i(" 命令會保存你在終端中執行的任何操作。如果你想知道你幾小時或幾天前做了什麼，那麼你可以查看它們。我知道我知道，我們可以使用上/下箭頭或 ",-1)),s[7]||(s[7]=t("code",null,"history",-1)),s[8]||(s[8]=i(" 命令查看以前運行的命令。但是，你無法查看這些命令的輸出。而 ",-1)),s[9]||(s[9]=t("code",null,"script",-1)),s[10]||(s[10]=i(" 命令記錄並顯示完整的終端會話活動。",-1))]),s[28]||(s[28]=d(`<p><code>script</code> 命令會在終端中創建你所做的所有事件的記錄。無論你是安裝程序，創建目錄/文件還是刪除文件夾，一切都會被記錄下來，包括命令和相應的輸出。這個命令對那些想要一份交互式會話拷貝作為作業證明的人有用。無論是學生還是導師，你都可以將所有在終端中執行的操作和所有輸出複製一份。</p><h3 id="在-linux-中使用-script-命令記錄終端中的所有內容" tabindex="-1">在 Linux 中使用 script 命令記錄終端中的所有內容 <a class="header-anchor" href="#在-linux-中使用-script-命令記錄終端中的所有內容" aria-label="Permalink to “在 Linux 中使用 script 命令記錄終端中的所有內容”">​</a></h3><p><code>script</code> 命令預先安裝在大多數現代 Linux 操作系統上。所以，我們不用擔心安裝。</p><p>讓我們繼續看看如何實時使用它。</p><p>運行以下命令啓動終端會話記錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ script -a my_terminal_activities</span></span></code></pre></div><p>其中，<code>-a</code> 標誌用於將輸出追加到文件（記錄）中，並保留以前的內容。上述命令會記錄你在終端中執行的所有操作，並將輸出追加到名為 <code>my_terminal_activities</code> 的文件中，並將其保存在當前工作目錄中。</p><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Script started, file is my_terminal_activities</span></span></code></pre></div><p>現在，在終端中運行一些隨機的 Linux 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ostechnix</span></span>
<span class="line"><span>$ cd ostechnix/</span></span>
<span class="line"><span>$ touch hello_world.txt</span></span>
<span class="line"><span>$ cd ..</span></span>
<span class="line"><span>$ uname -r</span></span></code></pre></div><p>運行所有命令後，使用以下命令結束 <code>script</code> 命令的會話：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ exit</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span>
<span class="line"><span>Script done, file is my_terminal_activities</span></span></code></pre></div><p>如你所見，終端活動已存儲在名為 <code>my_terminal_activities</code> 的文件中，並將其保存在當前工作目錄中。</p><p>要查看你的終端活動，只需在任何編輯器中打開此文件，或者使用 <code>cat</code> 命令直接顯示它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat my_terminal_activities</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Script started on Thu 09 Mar 2017 03:33:44 PM IST</span></span>
<span class="line"><span>[sk@sk]: ~&gt;$ mkdir ostechnix</span></span>
<span class="line"><span>[sk@sk]: ~&gt;$ cd ostechnix/</span></span>
<span class="line"><span>[sk@sk]: ~/ostechnix&gt;$ touch hello_world.txt</span></span>
<span class="line"><span>[sk@sk]: ~/ostechnix&gt;$ cd ..</span></span>
<span class="line"><span>[sk@sk]: ~&gt;$ uname -r</span></span>
<span class="line"><span>4.9.11-1-ARCH</span></span>
<span class="line"><span>[sk@sk]: ~&gt;$ exit</span></span>
<span class="line"><span>exit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Script done on Thu 09 Mar 2017 03:37:49 PM IST</span></span></code></pre></div><p>正如你在上面的輸出中看到的，<code>script</code> 命令記錄了我所有的終端活動，包括 <code>script</code> 命令的開始和結束時間。真棒，不是嗎？使用 <code>script</code> 命令的原因不僅僅是記錄命令，還有命令的輸出。簡單地説，腳本命令將記錄你在終端上執行的所有操作。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>就像我説的那樣，腳本命令對於想要保留其終端活動記錄的學生，教師和 Linux 用户非常有用。儘管有很多 CLI 和 GUI 可用來執行此操作，但 <code>script</code> 命令是記錄終端會話活動的最簡單快捷的方式。</p><p>就是這些。希望這有幫助。如果你發現本指南有用，請在你的社交，專業網絡上分享，並支持我們。</p><p>乾杯!</p><hr>`,26)),t("p",null,[s[12]||(s[12]=i("via: ",-1)),e(n,{href:"https://www.ostechnix.com/record-everything-terminal/"},{default:a(()=>[...s[11]||(s[11]=[i("https://www.ostechnix.com/record-everything-terminal/",-1)])]),_:1})]),t("p",null,[s[17]||(s[17]=i("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[13]||(s[13]=[i("SK",-1)])]),_:1}),s[18]||(s[18]=i(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[14]||(s[14]=[i("lujun9972",-1)])]),_:1}),s[19]||(s[19]=i(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:a(()=>[...s[15]||(s[15]=[i("geekpi",-1)])]),_:1}),s[20]||(s[20]=i(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:a(()=>[...s[16]||(s[16]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[23]||(s[23]=i("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[21]||(s[21]=[i("LCTT",-1)])]),_:1}),s[24]||(s[24]=i(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:a(()=>[...s[22]||(s[22]=[i("Linux中國",-1)])]),_:1}),s[25]||(s[25]=i(" 榮譽推出",-1))])])}const T=p(g,[["render",h]]);export{y as __pageData,T as default};
